const CACHE='pocket-shell-v17-three-games';
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./style.css?art=19','./app.js?art=19','./care.mjs?art=19','./ids.mjs?art=19','./catch-game.mjs?art=19','./rhythm-game.mjs?art=19','./bento-game.mjs?art=19','./domain.mjs?art=19','./garden.mjs?art=19','./garden-view.mjs?art=19','./garden-space.mjs?art=19','./growth.mjs?art=19','./growth-view.mjs?art=19','./pixel-sprites.mjs?art=19','./sprite-grid.mjs?art=19','./pets-native.png','./icon.svg','./manifest.webmanifest','./icon-192.png','./icon-512.png'])).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==location.origin||url.pathname.endsWith('/config.js'))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(r=>r||new Response('インターネットに接続して、もう一度開いてください。',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}}))))});
